import type{Metadata}from'next';import{notFound}from'next/navigation';import Link from'next/link';import{ArrowRight,Check}from'lucide-react';import PageHero from'@/components/PageHero';import{guides}from'@/lib/articles';export function generateStaticParams(){return guides.map(g=>({slug:g.slug}))}export async function generateMetadata({params}:{params:Promise<{slug:string}>}):Promise<Metadata>{const{slug}=await params,g=guides.find(x=>x.slug===slug);return g?{title:g.title,description:g.description,alternates:{canonical:'/journal/'+slug}}:{}}export default async function Guide({params}:{params:Promise<{slug:string}>}){const{slug}=await params,g=guides.find(x=>x.slug===slug);if(!g)notFound();return <><PageHero eyebrow={`${g.category} · ${g.read}`} title={g.title+'.'} intro={g.description}/><article className="article guideArticle"><div className="articleMeta"><span>Published September 3, 2026</span><span>Editorial team · PromptStudio AI</span></div><p className="lead">{g.intro}</p><nav className="toc"><b>IN THIS GUIDE</b>{g.sections.map((x,i)=><a href={'#s'+i} key={x.heading}>{i+1}. {x.heading}</a>)}</nav>{g.sections.map((s,i)=><section id={'s'+i} key={s.heading}><h2>{s.heading}</h2>{s.body.map(p=><p key={p}>{p}</p>)}</section>)}<div className="takeaways"><span>KEY TAKEAWAYS</span><ul>{g.takeaways.map(x=><li key={x}><Check size={17}/>{x}</li>)}</ul></div><Link className="articleCta" href="/prompts">Explore related prompts <ArrowRight/></Link></article></>}
